-- Function: public.sp_recalculate_invoice_balance
-- Backup generated on 2026-10-25 20:34:04

CREATE OR REPLACE PROCEDURE public.sp_recalculate_invoice_balance(IN p_invoice_id uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_total_paid NUMERIC; BEGIN     -- 1. Calculate sum of valid non-reversed completed payments     SELECT COALESCE(SUM(amount), 0)     INTO v_total_paid     FROM payments     WHERE invoice_id = p_invoice_id       AND status = 'Completed'       AND is_reversed = FALSE;      -- 2. Update invoice amount_paid, paid_at, and status     UPDATE invoices     SET amount_paid = v_total_paid,         paid_at = CASE              WHEN (total_amount - v_total_paid) <= 0 THEN COALESCE(paid_at, NOW())             ELSE NULL          END,         status = CASE             WHEN status = 'Void' THEN 'Void'             WHEN status = 'Draft' THEN 'Draft'             WHEN (total_amount - v_total_paid) <= 0 THEN 'Paid'             WHEN v_total_paid > 0 THEN 'PartiallyPaid'             ELSE 'Unpaid'         END,         updated_at = NOW()     WHERE id = p_invoice_id; END; $procedure$ ;
